def compute(vars):
    old_value = vars["v1"]
    new_value = vars["v2"]

    if old_value == 0:
        return None

    change_ratio = (new_value - old_value) / old_value
    return {
        "value": change_ratio,
        "trace": {
            "old_value": old_value,
            "new_value": new_value,
            "change": new_value - old_value,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": None
            }
        }
    }
